    41  void AccessibilitySceneManager::populateAccessibilityScene()
    42  {
    43      m_scene->clear();
    44      m_graphicsItems.clear();
    45
    46      QAccessibleInterface * rootInterface = m_window->accessibleRoot();
    47      if (!rootInterface)
    48          return;
    49
    50      populateAccessibilityScene(rootInterface, m_scene);
    51  }
