   187  void AccessibilitySceneManager::updateItem(QObject *object)
   188  {
   189      if (!object)
   190          return;
   191
   192      QAccessibleInterface *interface = QAccessible::queryAccessibleInterface(object);
   193      if (!interface)
   194          return;
   195
   196      updateItem(m_graphicsItems.value(object), interface);
   197  }
